// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testFuzz_property(address actor, uint256 value, uint32 lockTime) public {
        vm.assume(actor != address(0) && actor != address(c));
        value = bound(value, 1, 1 ether);
        // point C at a working log implementation
        FakeLog log = new FakeLog();
        c.SetLogFile(address(log));
        c.Initialized();
        vm.deal(actor, value);
        vm.prank(actor);
        bool ok;
        try c.Put{value: value}(lockTime) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: with a valid LogFile configured, ANY admissible Put must complete
        // without reverting; the mutant (Log never assigned) reverts on every Put.
        assertTrue(ok, "Put must succeed once a valid LogFile is set");
    }
}

contract FakeLog {
    function AddMessage(address, uint256, string memory) public pure {}
}
